  avatarUrl(filename) {
    if (!filename) {
      return 'assets/images/default-avatar.png';
    }
    if (filename.startsWith('http://') || filename.startsWith('https://') || filename.startsWith('/')) {
      return filename;
    }
    const lower = filename.toLowerCase();
    if (lower.startsWith('avatar-')) {
      return `${environment.assetsUrl}/avatars/${filename}`;
    }
    if (lower.startsWith('logo-')) {
      return `${environment.assetsUrl}/logos/${filename}`;
    }
    return `${environment.assetsUrl}/avatars/${filename}`;
  }
  // ============================================================================
  // 🚀 HISTORIQUE
  // ============================================================================
  loadNotificationHistory() {
    const token = localStorage.getItem('token');
    fetch(`${environment.apiUrl}/notifications/history`, {
      method: 'GET',
      headers: {
        'Authorization': token ? `Bearer ${token}` : ''
      }
    }).then(res => res.ok ? res.json() : {
      notifications: []
    }).then(data => {
      const items = data.notifications || [];
      const map = new Map();
      for (const it of items) {
        if (it && it.id) {
          map.set(it.id, it);
        }
      }
      const unique = Array.from(map.values());
      unique.sort((a, b) => {
        const ta = new Date(a.created_at || a.createdAt || 0).getTime() || 0;
        const tb = new Date(b.created_at || b.createdAt || 0).getTime() || 0;
        return tb - ta;
      });
      this.notificationsList = unique;
      this.unreadCount = this.notificationsList.filter(n => !n.is_read || n.is_read === 0).length;
      this.cdr.detectChanges();
